    a: a.matches.map((m) => `${m.file}:${m.line}: ${m.text.trim()}`),
    b: b.matches.map((m) => `${m.file}:${m.line}`),
    prs: (Array.isArray(list) ? list : []).map((p: any) => `${p.number} ${p.head.ref} ${p.title}`),
